mapper.sql:
WHERE crm_activities_cards.is_active = 1

    AND (
     customers.name LIKE CONCAT('%', #{filter.searchText}, '%')
    )


    AND DATE(crm_activities_cards.issue_date) >= #{filter.dateFrom}


    AND DATE(crm_activities_cards.issue_date) <= #{filter.dateTo}


    AND crm_activities_cards.action_status = #{filter.companyId}


    AND crm_activities_cards.created_by = #{filter.createdBy}


    AND customers.id = #{filter.organizationId}


    AND customers.id IN (SELECT customer_id FROM customer_cgroups WHERE cgroup_id = #{filter.organizationGroupId})

mapper.select:
SELECT IFNULL(customers.id, 0) AS organizationId, IFNULL(customers.name, 'NA') AS organizationName, crm_activities_cards.id AS id, crm_activities_status.name AS name, customer_contacts.contact_name AS contactName, crm_activities_status.name AS status, crm_activities_cards.issue_date AS `date`, crm_activities_cards.position AS `position`, crm_activities_cards.subject AS subject, crm_activities_cards.result_action AS `result`, crm_activities_cards.other AS other, CONCAT(users.first_name, ' ', users.last_name) AS createdBy FROM crm_activities_cards INNER JOIN users ON users.id = crm_activities_cards.created_by AND users.is_active = 1 INNER JOIN crm_activities_status ON crm_activities_cards.action_status = crm_activities_status.id INNER JOIN customer_contacts ON customer_contacts.id = crm_activities_cards.customer_contact_id AND customer_contacts.is_active IN (1,3) LEFT JOIN customers ON customers.id = customer_contacts.customer_id AND customers.is_active IN (1,3)
ORDER BY customers.id ASC, crm_activities_status.id ASC, customer_contacts.id ASC
LIMIT #{filter.page}, #{filter.rowsPerPage}
